-- Isolated only. Synthetic evidence is never imported into production.
RESET ROLE;SELECT set_config('request.jwt.claim.sub','',false);
INSERT INTO public.kipi_journals(id,journal_title,publication_year,source_url,discovery_url,archive_format) VALUES('60000000-0000-0000-0000-000000000001','Isolated fixture',2008,'https://www.kipi.go.ke/sites/default/files/test.pdf','https://www.kipi.go.ke/ip-journal','pdf');
INSERT INTO public.kipi_ip_records(id,journal_id,ip_category,original_registration_number,normalized_registration_number,applicant_name,source_page_number,extracted_text,record_hash,extraction_confidence) VALUES('60000000-0000-0000-0000-000000000002','60000000-0000-0000-0000-000000000001','patent','TEST2008','TEST2008','TEST Rights Holder',5,'Isolated publication passage','testhash',75);
SET ROLE authenticated;SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);SELECT set_config('request.jwt.claim.aal','aal1',false);
INSERT INTO public.ip_verification_requests(id,user_id,ip_category,registration_number,normalized_registration_number,applicant_name,declared_authorized) VALUES('60000000-0000-0000-0000-000000000003',auth.uid(),'patent','TEST2008','TEST2008','TEST Rights Holder',true);
SELECT pg_temp.expect_error($q$INSERT INTO ip_verification_requests(user_id,ip_category,registration_number,normalized_registration_number,applicant_name,declared_authorized,verification_status) VALUES(auth.uid(),'patent','T','T','Me',true,'VERIFIED')$q$,'row-level security','owner cannot submit a preapproved verification');
UPDATE ip_verification_requests SET verification_status='VERIFIED';
SELECT pg_temp.assert_true((SELECT verification_status='MANUAL_REVIEW_REQUIRED' FROM ip_verification_requests WHERE id='60000000-0000-0000-0000-000000000003'),'owner cannot edit verification decisions');
RESET ROLE;
INSERT INTO public.ip_verification_documents(verification_request_id,document_type,storage_path,original_filename,mime_type,file_size,sha256_hash,uploaded_by) VALUES('60000000-0000-0000-0000-000000000003','certificate','10000000-0000-0000-0000-000000000001/requests/test','fixture.pdf','application/pdf',20,'synthetic','10000000-0000-0000-0000-000000000001');
INSERT INTO storage.objects(bucket_id,name) VALUES('ip-verification-private','10000000-0000-0000-0000-000000000001/requests/test');
INSERT INTO public.ip_verification_results(verification_request_id,matched_record_id,result_status,record_match,evidence_summary) VALUES('60000000-0000-0000-0000-000000000003','60000000-0000-0000-0000-000000000002','PARTIALLY_VERIFIED',true,'Isolated matching publication');
SET ROLE authenticated;SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',false);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM ip_verification_requests),'unrelated user cannot read verification requests');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM ip_verification_documents),'unrelated user cannot read certificate metadata');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM storage.objects WHERE bucket_id='ip-verification-private'),'unrelated user cannot read private verification files');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',false);SELECT set_config('request.jwt.claim.aal','aal1',false);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM ip_verification_documents),'administrator needs MFA for review evidence');
SELECT pg_temp.expect_error($q$SELECT review_ip_verification('60000000-0000-0000-0000-000000000003','approve','test notes')$q$,'Administrator MFA','review operation requires administrator MFA');
SELECT set_config('request.jwt.claim.aal','aal2',false);
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM ip_verification_documents),'MFA administrator can read submitted certificate metadata');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM storage.objects WHERE bucket_id='ip-verification-private'),'MFA administrator can read private review files');
SELECT pg_temp.expect_error($q$SELECT review_ip_verification('60000000-0000-0000-0000-000000000003','approve','test notes','https://www.kipi.go.ke/')$q$,'website link alone','an official website link cannot upgrade publication to authenticated ownership');
SELECT review_ip_verification('60000000-0000-0000-0000-000000000003','approve','matching publication reviewed');
SELECT pg_temp.assert_true((SELECT verification_status='PARTIALLY_VERIFIED' FROM ip_verification_requests WHERE id='60000000-0000-0000-0000-000000000003'),'administrator approval of publication remains partial verification');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM ip_verification_reviews),'review decision retains history');
SELECT review_ip_verification('60000000-0000-0000-0000-000000000003','reopen','new evidence requires reassessment');
SELECT pg_temp.assert_true((SELECT administrator_decision IS NULL AND submission_status='submitted' FROM ip_verification_requests WHERE id='60000000-0000-0000-0000-000000000003'),'reopening removes decision lock without deleting history');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);SELECT set_config('request.jwt.claim.aal','aal1',false);
SELECT pg_temp.assert_true(public.claim_ip_verification('60000000-0000-0000-0000-000000000003'),'owner can reprocess a reopened request');
SELECT pg_temp.assert_true(NOT public.claim_ip_verification('60000000-0000-0000-0000-000000000003'),'verification processing has a single-flight lease');
RESET ROLE;SELECT set_config('request.jwt.claim.sub','',false);
