SELECT pg_temp.assert_true((SELECT introductory_expires_at=((published_at AT TIME ZONE 'Africa/Nairobi')+interval '3 months') AT TIME ZONE 'Africa/Nairobi' FROM listing_subscriptions WHERE service_listing_id='70000000-0000-0000-0000-000000000001'),'professional service receives three months from approval/publication');
